MODULE = PKG / "universal_market_adapter_replay_query_engine.py"
TEST = ROOT / "test_oi_194_universal_market_adapter_replay_query_engine.py"
INIT = PKG / "__init__.py"

MODULE_CODE = '"""\nOI-194 — Oracle Universal Market Adapter Replay Query Engine\n\nRead-only structured query layer for Universal Market Adapter replay artifacts.\n\nThis engine sits after Replay Search (OI-192) and Replay Filter (OI-193). It\naccepts replay registry/search/filter records and applies a canonical query\ncontract for selection, sorting, limiting, projection, aggregation metadata,\nexplainability, telemetry, and deterministic replay-safe result hashing.\n\nOracle remains the brain. Q Series remains the hand. This module never executes\ntrades, routes orders, submits orders, manages positions, or mutates market\nstate.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field, asdict\nfrom datetime import datetime, timezone\nfrom hashlib import sha256\nfrom typing import Any, Dict, Iterable, List, Mapping, Optional, Sequence, Tuple\nimport json\n\n\nREAD_ONLY_GUARDRAILS = {\n    "oracle_read_only": True,\n    "executes_trades": False,\n    "routes_orders": False,\n    "submits_orders": False,\n    "manages_positions": False,\n    "execution_owner": "Q_SERIES_ONLY",\n}\n\n\ndef _utc_now() -> str:\n    return datetime.now(timezone.utc).isoformat()\n\n\ndef _stable_json(value: Any) -> str:\n    return json.dumps(value, sort_keys=True, separators=(",", ":"), default=str)\n\n\ndef _hash(value: Any) -> str:\n    return sha256(_stable_json(value).encode("utf-8")).hexdigest()\n\n\ndef _safe_dict(value: Any) -> Dict[str, Any]:\n    if value is None:\n        return {}\n    if isinstance(value, Mapping):\n        return dict(value)\n    if hasattr(value, "to_dict"):\n        converted = value.to_dict()\n        if isinstance(converted, Mapping):\n            return dict(converted)\n    if hasattr(value, "__dict__"):\n        return dict(value.__dict__)\n    return {"value": value}\n\n\ndef _safe_list(value: Any) -> List[Any]:\n    if value is None:\n        return []\n    if isinstance(value, list):\n        return list(value)\n    if isinstance(value, tuple):\n        return list(value)\n    return [value]\n\n\ndef _lower(value: Any) -> str:\n    return str(value or "").lower()\n\n\ndef _field_value(record: Mapping[str, Any], field_path: str) -> Any:\n    current: Any = record\n    for part in str(field_path).split("."):\n        if isinstance(current, Mapping):\n            current = current.get(part)\n        else:\n            current = getattr(current, part, None)\n        if current is None:\n            return None\n    return current\n\n\n@dataclass(frozen=True)\nclass ReplayQueryClause:\n    field: str\n    operator: str\n    value: Any\n\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n\n\n@dataclass(frozen=True)\nclass ReplayQueryRequest:\n    query_id: str\n    clauses: List[ReplayQueryClause] = field(default_factory=list)\n    sort_by: Optional[str] = None\n    descending: bool = False\n    limit: Optional[int] = None\n    projection: List[str] = field(default_factory=list)\n    include_explainability: bool = True\n    context: Dict[str, Any] = field(default_factory=dict)\n\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n\n\n@dataclass(frozen=True)\nclass ReplayQueryMatch:\n    sequence: int\n    record_id: str\n    record_hash: str\n    record: Dict[str, Any]\n    matched_clauses: List[Dict[str, Any]]\n    explanation: Dict[str, Any]\n\n    def to_dict(self) -> Dict[str, Any]:\n        return asdict(self)\n\n\n@dataclass(frozen=True)\nclass ReplayQueryResult:\n    result_id: str\n    created_at: str\n    oracle_instance_id: str\n    module_id: str\n    module_name: str\n    query_id: str\n    input_count: int\n    matched_count: int\n    returned_count: int\n    query_hash: str\n    result_hash: str\n    read_only_guardrails: Dict[str, Any]\n    matches: List[ReplayQueryMatch]\n    telemetry: Dict[str, Any]\n    explainability: Dict[str, Any]\n\n    @property\n    def passed(self) -> bool:\n        return True\n\n    def to_dict(self) -> Dict[str, Any]:\n        data = asdict(self)\n        data["passed"] = True\n        return data\n\n\nclass UniversalMarketAdapterReplayQueryEngine:\n    """\n    Performs read-only structured queries against replay artifacts.\n\n    Query clauses use a deliberately small canonical operator set so the engine\n    remains deterministic, replayable, and easy to inspect:\n\n    - eq / ne\n    - contains\n    - in\n    - gte / lte / gt / lt\n    - exists\n    - startswith / endswith\n    """\n\n    module_id = "OI-194"\n    module_name = "Oracle Universal Market Adapter Replay Query Engine"\n\n    def __init__(self, oracle_instance_id: str = "oracle.default") -> None:\n        self.oracle_instance_id = oracle_instance_id\n        self._results: List[ReplayQueryResult] = []\n\n    def create_request(\n        self,\n        *,\n        query_id: str,\n        clauses: Optional[Iterable[Mapping[str, Any]]] = None,\n        sort_by: Optional[str] = None,\n        descending: bool = False,\n        limit: Optional[int] = None,\n        projection: Optional[Iterable[str]] = None,\n        include_explainability: bool = True,\n        context: Optional[Mapping[str, Any]] = None,\n    ) -> ReplayQueryRequest:\n        parsed_clauses = [self._normalize_clause(clause) for clause in _safe_list(clauses)]\n        return ReplayQueryRequest(\n            query_id=str(query_id),\n            clauses=parsed_clauses,\n            sort_by=sort_by,\n            descending=bool(descending),\n            limit=limit,\n            projection=[str(item) for item in _safe_list(projection)],\n            include_explainability=bool(include_explainability),\n            context=_safe_dict(context),\n        )\n\n    def query(\n        self,\n        records: Iterable[Any],\n        request: Optional[Any] = None,\n        **request_kwargs: Any,\n    ) -> ReplayQueryResult:\n        normalized_records = [_safe_dict(record) for record in records]\n\n        if request is None:\n            query_request = self.create_request(**request_kwargs)\n        elif isinstance(request, ReplayQueryRequest):\n            query_request = request\n        else:\n            request_data = _safe_dict(request)\n            query_request = self.create_request(\n                query_id=str(request_data.get("query_id") or request_kwargs.get("query_id") or "replay.query"),\n                clauses=request_data.get("clauses") or request_kwargs.get("clauses"),\n                sort_by=request_data.get("sort_by") or request_kwargs.get("sort_by"),\n                descending=bool(request_data.get("descending", request_kwargs.get("descending", False))),\n                limit=request_data.get("limit", request_kwargs.get("limit")),\n                projection=request_data.get("projection") or request_kwargs.get("projection"),\n                include_explainability=bool(request_data.get("include_explainability", True)),\n                context=request_data.get("context") or request_kwargs.get("context"),\n            )\n\n        matches: List[ReplayQueryMatch] = []\n        for record in normalized_records:\n            clause_results = [self._evaluate_clause(record, clause) for clause in query_request.clauses]\n            if all(item[0] for item in clause_results):\n                projected = self._project(record, query_request.projection)\n                record_id = self._record_id(record)\n                explanation = {\n                    "record_id": record_id,\n                    "matched": True,\n                    "clause_count": len(query_request.clauses),\n                    "operator_summary": [clause.operator for clause in query_request.clauses],\n                    "read_only_reason": "Replay query inspects metadata only and does not mutate registry state.",\n                } if query_request.include_explainability else {}\n                matches.append(ReplayQueryMatch(\n                    sequence=len(matches) + 1,\n                    record_id=record_id,\n                    record_hash=_hash(record),\n                    record=projected,\n                    matched_clauses=[detail for _, detail in clause_results],\n                    explanation=explanation,\n                ))\n\n        if query_request.sort_by:\n            matches.sort(\n                key=lambda match: self._sort_key(match.record, query_request.sort_by or ""),\n                reverse=query_request.descending,\n            )\n            matches = [self._replace_sequence(match, idx + 1) for idx, match in enumerate(matches)]\n\n        total_matched = len(matches)\n        if query_request.limit is not None:\n            matches = matches[: max(0, int(query_request.limit))]\n            matches = [self._replace_sequence(match, idx + 1) for idx, match in enumerate(matches)]\n\n        query_hash = _hash(query_request.to_dict())\n        result_payload = {\n            "query": query_request.to_dict(),\n            "matches": [match.to_dict() for match in matches],\n            "input_count": len(normalized_records),\n            "matched_count": total_matched,\n        }\n        result_hash = _hash(result_payload)\n\n        result = ReplayQueryResult(\n            result_id="oi194.query_result." + result_hash[:24],\n            created_at=_utc_now(),\n            oracle_instance_id=self.oracle_instance_id,\n            module_id=self.module_id,\n            module_name=self.module_name,\n            query_id=query_request.query_id,\n            input_count=len(normalized_records),\n            matched_count=total_matched,\n            returned_count=len(matches),\n            query_hash=query_hash,\n            result_hash=result_hash,\n            read_only_guardrails=dict(READ_ONLY_GUARDRAILS),\n            matches=matches,\n            telemetry={\n                "module_id": self.module_id,\n                "module_name": self.module_name,\n                "oracle_instance_id": self.oracle_instance_id,\n                "query_id": query_request.query_id,\n                "input_count": len(normalized_records),\n                "matched_count": total_matched,\n                "returned_count": len(matches),\n                "clause_count": len(query_request.clauses),\n                "projection_count": len(query_request.projection),\n                "sorted": bool(query_request.sort_by),\n                "limited": query_request.limit is not None,\n            },\n            explainability={\n                "purpose": "Execute deterministic read-only structured queries against replay artifacts.",\n                "read_only_reason": "The engine only selects and projects replay metadata; it never mutates artifacts or executes market actions.",\n                "execution_boundary": "Q Series remains the only execution engine.",\n                "canonical_contract": {\n                    "query_request": "ReplayQueryRequest",\n                    "query_result": "ReplayQueryResult",\n                    "query_match": "ReplayQueryMatch",\n                },\n                "supported_operators": ["eq", "ne", "contains", "in", "gte", "lte", "gt", "lt", "exists", "startswith", "endswith"],\n            },\n        )\n        self._results.append(result)\n        return result\n\n    def query_registered(self, registry_engine: Any, request: Optional[Any] = None, **request_kwargs: Any) -> ReplayQueryResult:\n        if not hasattr(registry_engine, "records"):\n            raise TypeError("registry_engine must expose a records() method")\n        return self.query(registry_engine.records(), request=request, **request_kwargs)\n\n    def latest_result(self) -> Optional[ReplayQueryResult]:\n        return self._results[-1] if self._results else None\n\n    def results(self) -> List[ReplayQueryResult]:\n        return list(self._results)\n\n    def telemetry_snapshot(self) -> Dict[str, Any]:\n        latest = self.latest_result()\n        return {\n            "module_id": self.module_id,\n            "module_name": self.module_name,\n            "oracle_instance_id": self.oracle_instance_id,\n            "result_count": len(self._results),\n            "latest_result_id": latest.result_id if latest else None,\n            "latest_query_id": latest.query_id if latest else None,\n            "latest_returned_count": latest.returned_count if latest else None,\n            "read_only_guardrails": dict(READ_ONLY_GUARDRAILS),\n        }\n\n    def _normalize_clause(self, clause: Any) -> ReplayQueryClause:\n        data = _safe_dict(clause)\n        return ReplayQueryClause(\n            field=str(data.get("field") or data.get("name") or ""),\n            operator=str(data.get("operator") or data.get("op") or "eq").lower(),\n            value=data.get("value"),\n        )\n\n    def _evaluate_clause(self, record: Mapping[str, Any], clause: ReplayQueryClause) -> Tuple[bool, Dict[str, Any]]:\n        actual = _field_value(record, clause.field)\n        expected = clause.value\n        op = clause.operator\n\n        if op == "eq":\n            passed = actual == expected\n        elif op == "ne":\n            passed = actual != expected\n        elif op == "contains":\n            passed = _lower(expected) in _lower(actual)\n        elif op == "in":\n            passed = actual in _safe_list(expected)\n        elif op == "gte":\n            passed = self._compare(actual, expected, ">=")\n        elif op == "lte":\n            passed = self._compare(actual, expected, "<=")\n        elif op == "gt":\n            passed = self._compare(actual, expected, ">")\n        elif op == "lt":\n            passed = self._compare(actual, expected, "<")\n        elif op == "exists":\n            passed = (actual is not None) is bool(expected)\n        elif op == "startswith":\n            passed = _lower(actual).startswith(_lower(expected))\n        elif op == "endswith":\n            passed = _lower(actual).endswith(_lower(expected))\n        else:\n            passed = False\n\n        return passed, {\n            "field": clause.field,\n            "operator": op,\n            "expected": expected,\n            "actual": actual,\n            "passed": passed,\n        }\n\n    def _compare(self, actual: Any, expected: Any, op: str) -> bool:\n        try:\n            a = float(actual)\n            b = float(expected)\n        except (TypeError, ValueError):\n            a = str(actual or "")\n            b = str(expected or "")\n        if op == ">=":\n            return a >= b\n        if op == "<=":\n            return a <= b\n        if op == ">":\n            return a > b\n        if op == "<":\n            return a < b\n        return False\n\n    def _project(self, record: Mapping[str, Any], projection: Sequence[str]) -> Dict[str, Any]:\n        if not projection:\n            return dict(record)\n        projected: Dict[str, Any] = {}\n        for field_name in projection:\n            projected[field_name] = _field_value(record, field_name)\n        return projected\n\n    def _record_id(self, record: Mapping[str, Any]) -> str:\n        for key in ("registration_id", "replay_id", "manifest_id", "certification_id", "validation_id", "audit_id", "id"):\n            if record.get(key):\n                return str(record[key])\n        return "record." + _hash(record)[:24]\n\n    def _sort_key(self, record: Mapping[str, Any], field_name: str) -> Tuple[int, str]:\n        value = _field_value(record, field_name)\n        return (1, "") if value is None else (0, str(value))\n\n    def _replace_sequence(self, match: ReplayQueryMatch, sequence: int) -> ReplayQueryMatch:\n        return ReplayQueryMatch(\n            sequence=sequence,\n            record_id=match.record_id,\n            record_hash=match.record_hash,\n            record=match.record,\n            matched_clauses=match.matched_clauses,\n            explanation=match.explanation,\n        )\n\n\ndef create_replay_query_engine(oracle_instance_id: str = "oracle.default") -> UniversalMarketAdapterReplayQueryEngine:\n    return UniversalMarketAdapterReplayQueryEngine(oracle_instance_id=oracle_instance_id)\n\n\n__all__ = [\n    "READ_ONLY_GUARDRAILS",\n    "ReplayQueryClause",\n    "ReplayQueryRequest",\n    "ReplayQueryMatch",\n    "ReplayQueryResult",\n    "UniversalMarketAdapterReplayQueryEngine",\n    "create_replay_query_engine",\n]\n'
TEST_CODE = 'from qseries_v2.oracle_intelligence.universal_market_adapter_replay_query_engine import (\n    READ_ONLY_GUARDRAILS,\n    ReplayQueryRequest,\n    UniversalMarketAdapterReplayQueryEngine,\n    create_replay_query_engine,\n)\n\n\nclass FakeRegistry:\n    def __init__(self, records):\n        self._records = records\n\n    def records(self):\n        return list(self._records)\n\n\ndef test_oi_194_universal_market_adapter_replay_query_engine():\n    engine = create_replay_query_engine("oracle.test")\n\n    records = [\n        {\n            "registration_id": "reg-001",\n            "manifest_id": "manifest-001",\n            "certification_id": "cert-001",\n            "adapter_id": "adp.kalshi",\n            "market_type": "prediction_market",\n            "symbol": "KXTEST",\n            "certification_level": "certified",\n            "confidence": 91,\n            "status": "registered",\n            "telemetry": {"source": "unit"},\n        },\n        {\n            "registration_id": "reg-002",\n            "manifest_id": "manifest-002",\n            "certification_id": "cert-002",\n            "adapter_id": "adp.polymarket",\n            "market_type": "prediction_market",\n            "symbol": "POLYTEST",\n            "certification_level": "certified_with_warnings",\n            "confidence": 74,\n            "status": "registered",\n            "telemetry": {"source": "unit"},\n        },\n        {\n            "registration_id": "reg-003",\n            "manifest_id": "manifest-003",\n            "certification_id": "cert-003",\n            "adapter_id": "adp.kalshi",\n            "market_type": "sports_market",\n            "symbol": "KXSPORT",\n            "certification_level": "not_certified",\n            "confidence": 50,\n            "status": "rejected",\n            "telemetry": {"source": "unit"},\n        },\n    ]\n\n    request = engine.create_request(\n        query_id="query-001",\n        clauses=[\n            {"field": "adapter_id", "operator": "eq", "value": "adp.kalshi"},\n            {"field": "confidence", "operator": "gte", "value": 80},\n        ],\n        sort_by="symbol",\n        projection=["registration_id", "adapter_id", "symbol", "confidence"],\n    )\n\n    result = engine.query(records, request)\n\n    assert result.passed is True\n    assert result.module_id == "OI-194"\n    assert result.input_count == 3\n    assert result.matched_count == 1\n    assert result.returned_count == 1\n    assert result.matches[0].record["registration_id"] == "reg-001"\n    assert result.matches[0].record["symbol"] == "KXTEST"\n    assert len(result.query_hash) == 64\n    assert len(result.result_hash) == 64\n    assert result.read_only_guardrails == READ_ONLY_GUARDRAILS\n    assert result.telemetry["clause_count"] == 2\n\n    limited = engine.query(\n        records,\n        query_id="query-002",\n        clauses=[{"field": "market_type", "operator": "eq", "value": "prediction_market"}],\n        sort_by="confidence",\n        descending=True,\n        limit=1,\n    )\n    assert limited.matched_count == 2\n    assert limited.returned_count == 1\n    assert limited.matches[0].record["registration_id"] == "reg-001"\n\n    contains = engine.query(\n        records,\n        query_id="query-003",\n        clauses=[{"field": "symbol", "operator": "contains", "value": "sport"}],\n    )\n    assert contains.matched_count == 1\n    assert contains.matches[0].record_id == "reg-003"\n\n    registry_result = engine.query_registered(\n        FakeRegistry(records),\n        query_id="query-004",\n        clauses=[{"field": "status", "operator": "eq", "value": "registered"}],\n    )\n    assert registry_result.matched_count == 2\n\n    exists_result = engine.query(\n        records,\n        query_id="query-005",\n        clauses=[{"field": "telemetry.source", "operator": "exists", "value": True}],\n    )\n    assert exists_result.matched_count == 3\n\n    snapshot = engine.telemetry_snapshot()\n    assert snapshot["result_count"] == 5\n    assert snapshot["read_only_guardrails"] == READ_ONLY_GUARDRAILS\n\n    direct = UniversalMarketAdapterReplayQueryEngine("oracle.direct")\n    assert direct.telemetry_snapshot()["result_count"] == 0\n\n\nif __name__ == "__main__":\n    test_oi_194_universal_market_adapter_replay_query_engine()\n    print("[PASS] OI-194 Universal Market Adapter Replay Query Engine")\n'

MODULE.write_text(MODULE_CODE, encoding="utf-8")
